const BASE = 'https://api.lokalise.com/api2/projects/';
const LANGS = '640,753';
const qs = 'include_translations=1&disable_references=1&limit=500&pagination=cursor&filter_translation_lang_ids=' + LANGS;
return [
  { json: { job: 'pco_all', url: BASE + '31393214664f295f94dd86.76792605/keys?' + qs } },
  { json: { job: 'mem_tag', url: BASE + '9933660066825e9a8005c8.58526829/keys?' + qs + '&filter_tags=' + encodeURIComponent('test_questions::fa') } }
];

const PCO = '31393214664f295f94dd86.76792605';
const FA = /(^|[-:_ ])fa$/i;
const out = { pco: [], mem: [], pco_all_count: 0, pco_tags_seen: {}, pco_fa_tags: {}, pages: 0, errors: [] };
const seen = {};
for (const it of $input.all()) {
  const r = it.json || {};
  const body = r.body || {};
  out.pages++;
  if (!Array.isArray(body.keys)) { out.errors.push({ status: r.statusCode, body: JSON.stringify(body).slice(0, 300) }); continue; }
  const isPco = body.project_id === PCO;
  for (const k of body.keys) {
    const sk = (isPco ? 'p' : 'm') + k.key_id;
    if (seen[sk]) continue; seen[sk] = 1;
    const name = typeof k.key_name === 'object' ? (k.key_name.web || k.key_name.other || k.key_name.ios || '') : k.key_name;
    const row = { id: k.key_id, k: name, tags: k.tags, archived: k.is_archived, desc: k.description || '', en: null, th: null, th_m: null, th_by: null, th_rev: null };
    for (const t of (k.translations || [])) {
      const v = typeof t.translation === 'string' ? t.translation : JSON.stringify(t.translation);
      if (t.language_iso === 'en') row.en = v;
      if (t.language_iso === 'th') { row.th = v; row.th_m = t.modified_at; row.th_by = t.modified_by_email; row.th_rev = t.is_reviewed; }
    }
    if (isPco) {
      out.pco_all_count++;
      let hit = false;
      for (const tg of (k.tags || [])) { out.pco_tags_seen[tg] = (out.pco_tags_seen[tg] || 0) + 1; if (FA.test(tg)) { hit = true; out.pco_fa_tags[tg] = (out.pco_fa_tags[tg] || 0) + 1; } }
      if (hit) out.pco.push(row);
    } else out.mem.push(row);
  }
}
return [{ json: out }];
